import { beforeAll, describe, expect, it } from "vitest";
import { NextRequest } from "next/server";
import { proxy, config } from "../proxy";
import { ADMIN_COOKIE } from "../lib/admin-auth-edge";
import { CLIENT_COOKIE } from "../lib/client-auth-edge";

// Why this test exists
// --------------------
// The nine /lab routes are design prototypes. They carried `noindex, nofollow`
// and nothing else, and noindex stops INDEXING, not INGESTION - robots.txt
// allows all sixteen named AI crawlers by name, deliberately, because being
// read by them is the product on /services/seo-aeo. /lab/work-treatments names
// an unlaunched product and states that it does not exist yet.
//
// The gate is owner-only rather than tenant-facing: a client has no reason to
// open an internal prototype. It is bypassed under `next dev` so that
// scripts/boards.mjs can still load /lab/board/<slug> off a local server to
// screenshot it - which means a test asserting the deny path MUST pin
// NODE_ENV, or it would pass for the wrong reason in a dev-like environment.

const SECRET = "test-only-session-secret-not-used-in-prod-0123456789";

async function mint(method: string, extra: Record<string, unknown> = {}): Promise<string> {
  const payload = btoa(JSON.stringify({ method, issuedAt: Date.now(), ...extra }));
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const mac = new Uint8Array(
    await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)),
  );
  return `${payload}.${Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("")}`;
}

function reqFor(url: string, cookieName?: string, cookieValue?: string): NextRequest {
  const headers = new Headers();
  if (cookieName && cookieValue) headers.set("cookie", `${cookieName}=${cookieValue}`);
  return new NextRequest(url, { headers });
}

const deniedToAdminLogin = (res: Response) =>
  (res.headers.get("location") || "").includes("/client/admin/login");

const LAB_ROUTES = [
  "/lab",
  "/lab/device-frames",
  "/lab/emphasis",
  "/lab/hero-aspect",
  "/lab/hero-v2",
  "/lab/illustrations",
  "/lab/orbit-hero",
  "/lab/serp-carousel",
  "/lab/work-treatments",
  "/lab/board/point-resolution",
];

beforeAll(() => {
  process.env.SESSION_SECRET = SECRET;
  // The gate no-ops under `next dev`. Pin production so the deny assertions
  // below are actually exercising the gate.
  // NODE_ENV is typed read-only. Cast rather than vi.stubEnv so the runtime
  // assignment stays byte-for-byte what it was - this is a type fix only.
  (process.env as Record<string, string>).NODE_ENV = "production";
});

describe("proxy() gate on /lab", () => {
  it("wiring: the middleware matcher covers /lab (never excluded)", () => {
    for (const m of config.matcher) {
      expect(m).not.toContain("lab");
    }
    expect(
      config.matcher.some((m) => new RegExp(`^${m}$`).test("/lab/work-treatments")),
    ).toBe(true);
  });

  it.each(LAB_ROUTES)("anonymous request to %s is denied", async (route) => {
    const res = await proxy(reqFor(`https://solaisoft.com${route}`));
    expect(deniedToAdminLogin(res)).toBe(true);
  });

  it("garbage cookie is denied", async () => {
    const res = await proxy(
      reqFor("https://solaisoft.com/lab/work-treatments", ADMIN_COOKIE, "nope.deadbeef"),
    );
    expect(deniedToAdminLogin(res)).toBe(true);
  });

  // A tenant session must not open an internal prototype. All gates share
  // SESSION_SECRET, so this is the assertion that catches a gate wired to the
  // wrong verifier - it would pass every anonymous test above and still be wrong.
  it("a valid CLIENT session cannot open /lab", async () => {
    const cookie = await mint("client", { slug: "station-street-fitness" });
    const res = await proxy(
      reqFor("https://solaisoft.com/lab/work-treatments", CLIENT_COOKIE, cookie),
    );
    expect(deniedToAdminLogin(res)).toBe(true);
  });

  // Positive control. Without it, a bug that redirected EVERYTHING would still
  // satisfy every negative assertion above.
  it("a valid OWNER session opens /lab", async () => {
    const cookie = await mint("owner");
    const res = await proxy(
      reqFor("https://solaisoft.com/lab/work-treatments", ADMIN_COOKIE, cookie),
    );
    expect(deniedToAdminLogin(res)).toBe(false);
    expect(res.status).toBe(200);
  });

  // Encoded and traversal variants must not dodge the prefix test, same as the
  // tenant prefixes. /%6cab decodes to /lab.
  it.each(["/%6cab/work-treatments", "/lab/../lab/work-treatments"])(
    "path variant %s is still gated",
    async (variant) => {
      const res = await proxy(reqFor(`https://solaisoft.com${variant}`));
      expect(deniedToAdminLogin(res)).toBe(true);
    },
  );

  it("a non-lab public route is unaffected", async () => {
    const res = await proxy(reqFor("https://solaisoft.com/pricing"));
    expect(deniedToAdminLogin(res)).toBe(false);
  });
});

