import path from "node:path";
import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";

// Minimal config. The gate test runs the edge middleware (proxy.ts) as plain
// Node code - NextRequest/NextResponse are built on web standards available in
// Node 20+, and the gate's transitive imports (lib/*-auth-edge.ts) are
// self-contained, so no DOM environment is needed. The "@" alias mirrors
// tsconfig paths for tests that import app code (the drop route).
const root = path.dirname(fileURLToPath(import.meta.url));

export default defineConfig({
  resolve: {
    alias: {
      "@": root,
      // Next's webpack build aliases the `server-only` package to a no-op for
      // server bundles; vitest has no such step, so the real package's
      // runtime throw ("cannot be imported from a Client Component") fires on
      // every test that transitively imports gsc.ts/ga4.ts/umami.ts. Same
      // no-op the framework already gives those files at build time.
      "server-only": path.resolve(root, "tests/stubs/server-only.ts"),
    },
  },
  test: {
    environment: "node",
    include: ["tests/**/*.test.ts"],
  },
});

