import { NextResponse, type NextRequest } from "next/server";
import { CONSULTING_LIVE, RESEARCH_LIVE } from "@/lib/flags";
import { CLIENT_COOKIE, sessionGrantsSlug, verifyClientSessionEdge } from "./lib/client-auth-edge";
import { ADMIN_COOKIE, verifyAdminSessionEdge } from "./lib/admin-auth-edge";
import { PORTAL_ACTIVE_SLUG_HEADER } from "./lib/portal/active-slug-header";

// Three gates (checked in order), plus the retired-namespace redirects:
//
// 1. /nomadik (RETIRED 2026-08-03) and /handymanclonakilty (RETIRED 2026-07-14):
//    the two legacy single-tenant gated docs, both migrated fully into the
//    /client portal, so each namespace now permanent-redirects to the portal
//    login pre-filled with the workspace. Kept as explicit redirects (not 404s)
//    so the founders' old bookmarks keep working.
//
// 2. /client gate (always on): the multi-tenant AEO client dashboard. A signed
//    cookie (sol_client) carries method 'client' plus one or more granted
//    slugs (an email-based sign-in allowlisted into several workspaces gets
//    all of them at once - no per-workspace pick). Passwords are verified
//    against the per-client repo config (content/clients/<slug>/config.ts,
//    authHash = sha256(CLIENT_AUTH_PEPPER + password)) - not a database, not
//    the VPS, and not a shared env password; see lib/client-auth.ts.
//    Onboarding a client is therefore a repo change and does need a deploy.
//    /client/admin is the owner-only surface nested inside it and is checked
//    FIRST, so a tenant session can never open it.
//
// 3. /lab gate (always on in a deployed build): the nine design-prototype
//    routes. They carry noindex, which stops Google indexing them but does
//    NOT stop the sixteen AI crawlers robots.txt names by allowing them - and
//    /lab/work-treatments states an unlaunched product name and its status.
//    Owner cookie only, same as /client/admin. Bypassed in development so
//    `npm run boards` can still load /lab/board/<slug> off a local dev server
//    to screenshot it.
//
// 3.5. /internal gate (always on): owner-only personal-tooling pages, same
//    cookie as /lab. Currently just /internal/ingest - the hosted summaries
//    from the personal email-ingest automation. /api/internal/* is exempt
//    from THIS gate because it authenticates with its own bearer token
//    (lib/internal-ingest/auth.ts): the automation is a headless script, not
//    a browser, so it has no owner cookie to present.
//
// 4. Site-wide pre-launch gate (DORMANT by default): with no SITE_GATE_PASSWORD
//    set this is a no-op. Turned on/off purely by adding/removing
//    SITE_GATE_PASSWORD in Vercel - no code change. While active it returns 401
//    to everyone, including crawlers; remove the env var to launch.
/** The workspace slug of the same-origin portal page a request came from
 *  (Referer /client/<slug>/...), or null. Unverified here: the API route
 *  checks it against the session before acting on it. */
function refererWorkspaceSlug(req: NextRequest): string | null {
  const referer = req.headers.get("referer");
  if (!referer) return null;
  let url: URL;
  try {
    url = new URL(referer);
  } catch {
    return null;
  }
  if (url.origin !== req.nextUrl.origin) return null;
  const m = url.pathname.match(/^\/client\/([a-z0-9-]+)(?:\/|$)/);
  return m ? m[1] : null;
}

export async function proxy(req: NextRequest) {
  const raw = req.nextUrl.pathname;

  // Per-tenant reference docs are served as static files under public/client-docs.
  // Next/Vercel's static resolver percent-DECODES the URL before mapping it to a
  // file, but req.nextUrl.pathname is NOT decoded - so a raw string match here
  // would miss an encoded path (e.g. /client-docs/%6eomadik/x.html) and let it
  // fall through to the static file undecoded. Decode fully (looping is safe -
  // over-decoding only ever gates MORE) and lowercase to fold case, then gate on
  // BOTH the decoded and raw prefixes so nothing under a gated prefix can slip
  // past.
  //
  // Decode leniently, one %XX token at a time, rather than with a single
  // decodeURIComponent(dec) call: that built-in throws on the WHOLE string if
  // ANY token in it is malformed, which would let one bad byte anywhere in the
  // path (e.g. a trailing %zz) hide a perfectly valid /%6eomadik/ earlier in
  // the same path from this decoder while Vercel's resolver may still tolerate
  // it. Decoding token-by-token means a malformed token just stays literal
  // instead of aborting the whole decode.
  const lenientDecodeOnce = (s: string) =>
    s.replace(/%[0-9A-Fa-f]{2}/g, (tok) => {
      try {
        return decodeURIComponent(tok);
      } catch {
        return tok;
      }
    });
